runs.cmd:
S=$(curl -sS -D - -o /dev/null http://127.0.0.1:27500/mcp -H 'content-type: application/json' -H 'accept: application/json, text/event-stream' -d '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-11-25","capabilities":{},"clientInfo":{"name":"raw","version":"0"}}}' | grep -i mcp-session-id | cut -d' ' -f2 | tr -d ''); curl -sS -o /dev/null -w 'initialized notification: %{http_code}
' http://127.0.0.1:27500/mcp -H 'content-type: application/json' -H 'accept: application/json, text/event-stream' -H "mcp-session-id: $S" -H 'mcp-protocol-version: 2025-11-25' -d '{"jsonrpc":"2.0","method":"notifications/initialized"}'; curl -sS -w '
tools/list right away: %{http_code}
' http://127.0.0.1:27500/mcp -H 'content-type: application/json' -H 'accept: application/json, text/event-stream' -H "mcp-session-id: $S" -H 'mcp-protocol-version: 2025-11-25' -d '{"jsonrpc":"2.0","id":2,"method":"tools/list"}' | grep -E '^data|tools/list' | cut -c1-120; sleep 5; curl -sS -w '
tools/list after 5 s idle: %{http_code}
' http://127.0.0.1:27500/mcp -H 'content-type: application/json' -H 'accept: application/json, text/event-stream' -H "mcp-session-id: $S" -H 'mcp-protocol-version: 2025-11-25' -d '{"jsonrpc":"2.0","id":3,"method":"tools/list"}'
